"""Build Kazakh thesis and defense PDFs plus editable HTML from saved results.
Run with the bundled document Python. No training or invented metric values.
"""
from pathlib import Path
import json,html,re
from document_results_v3 import add_results, verification_text, add_defense_update
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_JUSTIFY,TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output';OUT.mkdir(exist_ok=True)
def read(name):return json.loads((ROOT/'reports'/name).read_text(encoding='utf-8'))
B=read('brfss_results.json');U=read('uci_results.json');A=read('brfss_data.json');UA=read('uci_data.json');ENV=read('environment.json');SCHEMA=read('schema.json')
L=next(r for r in B['full'] if r['name']==B['selection']['deployed_model']);G=next(r for r in B['full'] if r['name']=='LightGBM');UF=next(r for r in U['benchmark'] if r['name']==U['selection']['deployed_model'])
M=L['metrics'];P=B['protocol'];N=lambda x:f'{x:,}'.replace(',',' ');F=lambda x:f'{x:.4f}'
pdfmetrics.registerFont(TTFont('DV',str(ROOT/'assets/DejaVuSans.ttf')))
styles=getSampleStyleSheet()
for name in styles.byName:styles[name].fontName='DV'
styles.add(ParagraphStyle(name='BodyKK',fontName='DV',fontSize=10.5,leading=16,spaceAfter=9,alignment=TA_JUSTIFY))
styles.add(ParagraphStyle(name='H1KK',fontName='DV',fontSize=16,leading=22,spaceBefore=14,spaceAfter=14,keepWithNext=True,textColor=colors.black))
styles.add(ParagraphStyle(name='H2KK',fontName='DV',fontSize=12,leading=18,spaceBefore=13,spaceAfter=8,keepWithNext=True,textColor=colors.black))
styles.add(ParagraphStyle(name='TitleKK',fontName='DV',fontSize=22,leading=31,spaceAfter=24,textColor=colors.black))
styles.add(ParagraphStyle(name='SmallKK',fontName='DV',fontSize=8,leading=12,spaceAfter=7))
styles.add(ParagraphStyle(name='CellKK',fontName='DV',fontSize=8,leading=11))

class Document:
    def __init__(self,title):self.title=title;self.story=[];self.html=[]
    def p(self,text,style='BodyKK'):
        self.story.append(Paragraph(html.escape(str(text)).replace('\n','<br/>'),styles[style]));self.html.append('<p>'+html.escape(str(text)).replace('\n','<br>')+'</p>')
    def h(self,text,level=1):
        self.story.append(Paragraph(html.escape(text),styles['H1KK' if level==1 else 'H2KK']));self.html.append(f'<h{level}>'+html.escape(text)+f'</h{level}>')
    def page(self):self.story.append(PageBreak());self.html.append('<div class="page-break"></div>')
    def table(self,headers,rows,widths=None):
        data=[[Paragraph(html.escape(str(v)),styles['CellKK']) for v in row] for row in [headers]+rows]
        t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dfe8ee')),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#D9D9D9')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f7f9fb')])]))
        self.story.extend([t,Spacer(1,12)]);self.html.append('<table><thead><tr>'+''.join('<th>'+html.escape(str(v))+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>')
    def figure(self,name,caption,width=480):
        from PIL import Image as PILImage
        path=ROOT/'reports/figures'/f'{name}.png';w,h=PILImage.open(path).size
        self.story.append(KeepTogether([Image(str(path),width=width,height=width*h/w),Spacer(1,6),Paragraph(html.escape(caption),styles['SmallKK'])]));self.html.append(f'<figure><img src="../reports/figures/{name}.png"><figcaption>'+html.escape(caption)+'</figcaption></figure>')
    def save(self,stem):
        def footer(c,doc):
            c.setFont('DV',8);c.setFillColor(colors.HexColor('#66736c'));c.drawString(50,29,'CardioResearch · 2026');c.drawRightString(A4[0]-50,29,str(doc.page))
        doc=SimpleDocTemplate(str(OUT/(stem+'.pdf')),pagesize=A4,rightMargin=50,leftMargin=50,topMargin=48,bottomMargin=48,title=self.title,author='CardioResearch')
        doc.build(self.story,onFirstPage=footer,onLaterPages=footer)
        css='body{font-family:Arial,sans-serif;max-width:900px;margin:40px auto;color:#182c23;line-height:1.7;padding:0 20px}h1,h2{color:#000}table{border-collapse:collapse;width:100%;font-size:13px;margin:20px 0}th,td{border:1px solid #ddd;padding:9px;text-align:left}th{background:#dfe8ee}img{max-width:100%}figcaption{font-size:12px;color:#666}@media print{.page-break{break-before:page}body{margin:0}}'
        (OUT/(stem+'.html')).write_text('<!doctype html><html lang="kk"><meta charset="utf-8"><title>'+html.escape(self.title)+'</title><style>'+css+'</style><body>'+''.join(self.html)+'</body></html>',encoding='utf-8')

def paragraphs(doc,text):
    for p in text.strip().split('\n\n'):doc.p(p.strip())

def thesis():
    d=Document('Жүрек қан тамырлары ауруларын жіктеуге арналған машиналық оқыту модельдері')
    d.p('ДИПЛОМДЫҚ ЖОБА МӘТІНІНІҢ ЖҰМЫС НҰСҚАСЫ',style='SmallKK');d.p('Жүрек-қан тамырлары ауруларын болжауға арналған машиналық оқыту модельдерін әзірлеу',style='TitleKK')
    d.p('Сарсенбаева Айдана · Жасанды интеллект технологиялары · ЖИТ-31. Жетекші: Жеткенбай Лена. Қорғау жылы: 2027.')
    d.p('17.11.2026: 3.0 нұсқасының сақталған нәтижелерімен толықтырылған редакциялық нобай. Автордың тексеруі, университет үлгісіне сай ресімдеу және түпкілікті мақұлдау қажет. ЖИ көмегімен жаңартылған; бұл 100 бетке дайындалған соңғы қолжазба емес.',style='SmallKK')
    d.p('CardioResearch интерактивті зерттеу қосымшасы',style='H2KK')
    paragraphs(d,f'''Бұл жұмыс CDC BRFSS 2023 сауалнамасы мен UCI Cleveland клиникалық деректері негізінде аурудың тіркелген болуын жіктейтін модельдерді зерттейді. Зерттеуде болашақта пайда болатын оқиға емес, қолда бар белгілер мен бұрын хабарланған диагноз арасындағы байланыс бағаланады.

Негізгі тәжірибеде {N(A['retained'])} бақылау қолданылды. Үлкен деректердегі валидациялық Average Precision өлшемі бойынша логистикалық регрессия таңдалды. Оның тәуелсіз тесттегі ROC-AUC көрсеткіші {F(M['roc_auc'])}, Average Precision көрсеткіші {F(M['average_precision'])} болды. UCI тәжірибесі бөлек жүргізіліп, Random Forest сыртқы кросс-валидацияда орташа Average Precision {F(UF['metrics']['average_precision'])} көрсетті.

Жұмыс нәтижесі модельдерді оқыту және бағалау коды, сақталған эксперименттер, веб-қосымша, жеке болжам түсіндірмесі және есепті экспорттау мүмкіндігінен тұрады. Нәтижелер клиникалық қолдануға рұқсат немесе аурудың болашақ қаупінің расталған бағасы ретінде қарастырылмайды.''')
    d.p('2027 жыл · нәтижелер 2026 жылғы 17 қарашада тексерілді',style='SmallKK');d.page()
    d.h('Мазмұны')
    sections=['Кіріспе','1 Машиналық оқыту арқылы медициналық жіктеу','2 Деректер және алдын ала өңдеу','3 Эксперимент әдістемесі','4 Нәтижелерді салыстыру және талқылау','5 Қосымшаның архитектурасы және іске асырылуы','6 Тексеру және қайта өндіру','Қорытынды','Пайдаланылған дереккөздер','Қосымша А Белгілер сөздігі','Қосымша Ә Тәжірибе параметрлері']
    for s in sections:d.p(s)
    d.h('Қысқартулар',2)
    d.table(['Белгі','Мағынасы'],[['BRFSS','Behavioral Risk Factor Surveillance System'],['UCI','University of California Irvine деректер репозиторийі'],['AP','Average Precision'],['ROC-AUC','ROC қисығы астындағы аудан'],['CV','Кросс-валидация'],['SHAP','Shapley Additive Explanations'],['API','Қолданбалық бағдарламалау интерфейсі']],[75,420]);d.page()
    d.h('Кіріспе')
    paragraphs(d,'''Медициналық және сауалнамалық деректердегі көптеген белгілер бір-бірімен байланысты. Бір ғана көрсеткішке сүйенген бағалау осы байланысты толық сипаттай алмауы мүмкін. Машиналық оқыту бірнеше белгіні бірге талдауға мүмкіндік береді, алайда оның сапасын деректердің көлемімен немесе алгоритм атауымен ғана дәлелдеуге болмайды. Бағалау процедурасының дұрыстығы, дереккөздің түсініктілігі және қателердің ашық көрсетілуі негізгі орын алады.

Жобаның өзектілігі ашық денсаулық деректерін ғылыми талаптарға сай өңдеу, әртүрлі алгоритмдерді бірдей шарттарда салыстыру және нәтижені қарапайым пайдаланушыға түсіндіру қажеттілігімен анықталады. Жүйе дәрігердің орнын басуға арналмаған. Ол деректерге негізделген жіктеудің мүмкіндігі мен шектеулерін көрсететін зерттеу құралы ретінде жасалды.

Зерттеудің мақсаты — жүрек-қан тамырлары жағдайларына қатысты тіркелген белгіні жіктейтін модельдерді әзірлеу, олардың сапасын қайталанатын эксперимент арқылы салыстыру және нақты оқытылған модельмен жұмыс істейтін интерактивті қосымша жасау.

Зерттеу объектісі — BRFSS респонденттерінің денсаулық туралы жауаптары және Cleveland пациенттерінің клиникалық көрсеткіштері. Зерттеу пәні — осы белгілерден бинарлық нәтижені бағалайтын машиналық оқыту әдістері, ықтималдықтарды калибрлеу және модель шешімін түсіндіру тәсілдері.

Мақсатқа жету үшін деректердің шығу тегін тексеру, мақсатты айнымалыны анықтау, арнайы жауап кодтарын өңдеу, ақпараттың ағып кетуін болдырмайтын бөлуді құру, жеті алгоритмді оқыту, қателер мен белгісіздікті бағалау, интерфейсті жүзеге асыру және жұмысты қайта өндіру нұсқаулығын дайындау міндеттері орындалды.

Жұмыстың практикалық маңызы — бір жүйеде сақталған дайын модель, айнымалылар сөздігі, есептеу нәтижелері және түсіндірілетін интерфейстің болуы. Қолданушы анкетаны толтырып, модель бағасын, таңдалған шекті және факторлар үлесін көре алады. Зерттеуші сол кодпен деректерді дайындау мен оқытуды қайта жүргізе алады.

Өзіндік үлес жаңа классификатор ұсынудан тұрмайды. Ол әртүрлі алгоритмдерді нақты деректерде әдістемелік тұрғыдан салыстыру, калибрлеу мен шек әсерін бөлу, деректердің екі түрін араластырмай зерттеу және нәтижелерді жұмыс істейтін қосымшаға жеткізу арқылы көрінеді.''')
    d.h('Зерттеу гипотезалары',2)
    paragraphs(d,'''Бірінші гипотеза: күрделі ансамбльдер қарапайым логистикалық регрессиядан барлық жағдайда басым болмайды. Екінші гипотеза: кластарды теңгеру сезімталдықты арттыра алады, бірақ ықтималдықтардың сапасын нашарлатуы мүмкін. Үшінші гипотеза: белгілер санын қысқарту интерфейсті жеңілдеткенімен, модельдің ажырату қабілетін төмендетуі ықтимал. Төртінші гипотеза: бір ғана Accuracy көрсеткіші оң класс сирек кездескенде модельдің практикалық мінез-құлқын жеткілікті сипаттамайды.

Бұл гипотезалар алдын ала күтілетін бағыттар ретінде берілді. Оларды тексеру нақты орындалған тәжірибелерге сүйенеді; қолайлы сан алу үшін тест нәтижесіне қарай модель немесе мақсат өзгертілмейді.''');d.page()
    d.h('1 Машиналық оқыту арқылы медициналық жіктеу')
    d.h('1.1 Жіктеу мен уақыттық болжамның айырмашылығы',2)
    paragraphs(d,'''Бинарлық жіктеуде модель X белгілер жиыны үшін Y=1 класының бағасын шығарады. Бұл жобада BRFSS үшін Y=1 — адамның бұрын инфаркт немесе стенокардия/ишемиялық жүрек ауруы болғанын хабарлауы. UCI үшін Y=1 — деректерде аурудың бар екенін білдіретін диагностикалық код.

Болашақ оқиғаны болжау үшін бастапқы сәт, кейінгі бақылау мерзімі және сол аралықтағы оқиғалар қажет. Қолданылған BRFSS бір кезеңдегі сауалнама болғандықтан, модель жауабын «келесі он жылдағы инфаркт қаупі» деп атау дұрыс емес. Жалпы денсаулық бағасы мен белсенділік аурудан кейін өзгеруі де мүмкін. Осы себеппен алынған байланыстар алдын алу әсерін немесе себептілікті білдірмейді.''')
    d.h('1.2 Салыстырылатын алгоритмдер',2)
    paragraphs(d,'''Логистикалық регрессия белгілердің сызықтық комбинациясын логистикалық функция арқылы ықтималдыққа түрлендіреді. Оның артықшылығы — есептеудің салыстырмалы жеңілдігі және тұрақты базалық нәтиже. Категориялар one-hot кодтаудан өтеді, ал сандық көрсеткіштер масштабталады. Регуляризация коэффициенттері шамадан тыс үлкен салмақтардың пайда болуын шектейді.

Шешім ағашы белгілер кеңістігін шарттар арқылы бөледі. Терең ағаш оқыту деректерін тым нақты есте сақтауы мүмкін, сондықтан максималды тереңдік пен жапырақтағы ең аз бақылау саны реттеледі. Random Forest бірнеше кездейсоқтандырылған ағаштың нәтижесін біріктіреді; бұл жеке ағаштың тұрақсыздығын азайтуға бағытталған.

Тірек векторлар әдісінің сызықтық нұсқасы кластар арасындағы шекараны құрады. Үлкен таңдамада ядролық әдістің есептеу құны жоғары болуы мүмкін болғандықтан, LinearSVC таңдалды. Ықтималдық шығару үшін оның бағасы оқыту бөліктерінің ішіндегі калибрлеумен түрлендіріледі.

KNN объектіні көрші бақылаулардың кластары арқылы бағалайды. Ол масштаб пен қашықтыққа сезімтал, ал болжау уақыты оқыту жиыны ұлғайған сайын артады. LightGBM ағаштарды кезеңмен қосатын градиенттік бустинг әдісі ретінде енгізілді. MLP шағын нейрондық желісі сызықтық емес тәуелділіктерді зерттеу үшін қолданылды; оның болуы автоматты түрде жоғары нәтиже береді деген болжам жасалмады.

DummyClassifier оң класс жиілігін ғана пайдаланады. Ол үлгілік белгілерді үйренбейді және күрделі модельдердің шынымен ақпарат қосатынын тексеретін бақылау нүктесі болып табылады. Оны негізгі алгоритмдермен бірге көрсету теңгерімсіз деректерде Accuracy нәтижесін түсіндіруге көмектеседі.''')
    d.h('1.3 Бағалау көрсеткіштері',2)
    paragraphs(d,'''ROC-AUC модельдің оң және теріс объектілерді ранжирлеу қабілетін сипаттайды. Average Precision оң болжам дәлдігі мен сезімталдықтың өзгерісін біріктіреді және осы жұмыста негізгі таңдау өлшемі ретінде пайдаланылды. AP трапециялық PR-AUC есебімен бірдей деп қарастырылмайды.

Сезімталдық TP/(TP+FN) формуласымен анықталып, нақты оң бақылаулардың қаншасы табылғанын көрсетеді. Ерекшелік TN/(TN+FP) теріс бақылаулардың дұрыс анықталуын сипаттайды. Precision TP/(TP+FP) оң болжамдардың қандай бөлігі дұрыс екенін көрсетеді. F1 осы екі көрсеткіштің гармониялық ортасы болып табылады.

Brier score болжанған ықтималдық пен бинарлық жауаптың квадрат айырмасының орташа мәніне тең. Оның төмен болуы жақсы, бірақ ол тек калибрлеуді ғана емес, жалпы ықтималдық болжамының сапасын да қамтиды. Сондықтан ол калибрлеу графигімен бірге қарастырылды. Метрикалардың анықтамалары мен іске асырылуы scikit-learn құжаттамасымен салыстырылды [3].''');d.page()
    d.h('2 Деректер және алдын ала өңдеу')
    d.h('2.1 BRFSS деректерінің паспорты',2)
    paragraphs(d,f'''CDC BRFSS 2023 бастапқы архивінен {N(A['raw_rows'])} жол және {A['raw_columns']} баған оқылды. Дерек бірлігі — сауалнамаға жауап берген респондент. Түпнұсқа архив өзгертілмеді; оның көлемі мен SHA-256 бақылау сомасы sources.json файлында сақталды. Айнымалы мағыналары жергілікті HTML анықтамалығынан алынып, таңдалған үзінділер жеке есепке жазылды [1].

Мақсат CVDINFR4 және CVDCRHD4 жауаптарынан құрылды. Егер кемінде бір жауап 1 болса, мақсат 1; екі жауап та 2 болса, мақсат 0. Қалған комбинацияларда мақсат белгісіз деп есептелді. Осы ереже деректегі _MICHD айнымалысымен барлық жазба бойынша салыстырылып, айырмашылық табылған жоқ. Белгісіз мақсатты {N(A['unknown_target_removed'])} жазба шығарылып, {N(A['retained'])} бақылау сақталды.

Бастапқы деректердің ресми онлайн нұсқасы өзгеруі мүмкін болғандықтан, бұл жұмыс нәтижелерін нақты жергілікті архив пен оның бақылау сомасына қатысты түсіндіру керек. Дипломда архив атауы мен есептеу күні бірге сақталған. Дереккөздің онлайн сипаттамасы нақты талданған файлдың нұсқасын алмастырмайды.''')
    d.table(['Қадам','Жазба саны','Шешім'],[['Бастапқы XPT',N(A['raw_rows']),'Барлық жол оқылды'],['Мақсаты белгісіз',N(A['unknown_target_removed']),'Оқыту мен бағалаудан шығарылды'],['Қалған бақылау',N(A['retained']),'Белгілердегі пропусктар сақталды'],['Негізгі оқыту',N(P['fit']),'Модель параметрлерін үйрену'],['Калибрлеу',N(P['calibration']),'Sigmoid параметрлерін үйрену'],['Валидация',N(P['validation']),'Модель және шек таңдау'],['Тест',N(P['test']),'Соңғы тәуелсіз бағалау']],[150,80,265])
    d.h('2.2 Белгілердің мағынасы және арнайы кодтар',2)
    paragraphs(d,'''BRFSS үшін он бір белгі алдын ала таңдалды: жас тобы, жыныс, дене салмағы индексі, темекі шегу мәртебесі, соңғы айдағы дене белсенділігі, диабет, жоғары қан қысымы, жоғары холестерин, жалпы денсаулық бағасы және соңғы 30 күндегі физикалық әрі эмоциялық жайсыздық күндері.

Жас 13 санатпен ұсынылды; белгісіз санат жеке жас ретінде қолданылмайды. BMI бастапқы _BMI5 айнымалысын 100-ге бөлу арқылы алынды. PHYSHLTH және MENTHLTH үшін 88 коды нөл күнді, ал 77 және 99 белгісіз жауапты білдіреді. Диабет пен жоғары қысым сұрақтарындағы жүктілікке ғана қатысты жауап жеке санат ретінде сақталды. Осылайша «белгісіз», «жоқ» және арнайы клиникалық жағдайлар бір мәнге біріктірілмеді.

Категориялық пропусктар -1 арқылы кодталып, жеке one-hot санатына айналады. Сандық пропусктар оқыту бөлігінің медианасымен толтырылады. Медиана мен масштаб параметрлері әрбір CV қадамында қайта үйреніледі. Белгісіз мақсат толтырылмайды, себебі ол жасанды жауап енгізуге әкеледі.

Идентификаторлар, сауалнама салмақтары және мақсаттың құрамдас сұрақтары кіріс белгілеріне қосылмады. Бірдей жауаптары бар екі респондент автоматты түрде дубликат ретінде жойылған жоқ. Қайталанатын респондентті тексеру үшін штат пен PSU жұбы қолданылды; тексерілген жиында қайталау табылмады.''')
    d.h('2.3 UCI клиникалық деректері',2)
    paragraphs(d,'''UCI архивінде бірнеше орталықтың деректері бар. Алдымен Cleveland, Hungary, Switzerland және VA өңделген файлдары қаралып, белгілердің толықтығы салыстырылды. Негізгі қосымша тәжірибе үшін 303 бақылауы бар Cleveland таңдалды. Бұл таңдау тест сапасына сүйенбейді: мақсат — бір орталықтағы бірізді 13 белгімен әдістемелік салыстыру жасау [2].

Cleveland белгілеріне жас, жыныс, кеуде ауыруының түрі, тыныштықтағы қысым, холестерин, ашқарындағы глюкоза категориясы, тыныштықтағы ЭКГ, жүктемедегі максималды жүрек соғу жиілігі, жүктемелік стенокардия, ST депрессиясы, ST еңісі, флюороскопиядағы тамыр саны және таллий сынағы кіреді. Бастапқы num мәні 0 болса теріс, 1–4 болса оң класс деп белгіленді.

BRFSS белгілері көбіне адамның хабарлаған жағдайын сипаттаса, UCI арнайы клиникалық тексерулерді қамтиды. Сондықтан екі жиынды біріктіру немесе бірінің метрикасын екіншісінің сыртқы тексеруі деп атау әдістемелік қате болар еді. Нәтижелер екі бөлек тәжірибе ретінде беріледі.''')
    d.table(['Орталық','Бақылау','Орташа пропуск үлесі'],[[k,N(v['n']),f"{v['missing_fraction']*100:.1f}%"] for k,v in UA['centers_audit'].items()],[200,110,185]);d.page()
    d.h('3 Эксперимент әдістемесі')
    d.h('3.1 Деректерді бөлу және салыстыру шарттары',2)
    paragraphs(d,f'''Негізгі мақсатты ереже мен белгілер тізімі анықталғаннан кейін BRFSS-тің 20%-ы тест ретінде бөлінді. Қалған деректер негізгі оқыту, калибрлеу және валидация бөліктеріне ажыратылды. Барлық бөлу стратификациямен және {ENV['seed']} кездейсоқтық тұқымымен орындалды. Жол идентификаторлары brfss_splits.json файлында сақталды; жиындар арасында қиылысу жоқ екені тестпен тексерілді.

Жеті алгоритмді бірдей есептеу шартында салыстыру үшін негізгі оқыту бөлігінен {N(P['benchmark_train'])} бақылау алынды. Барлық модель дәл осы жолдарда үйренді және тест ішінен алдын ала бекітілген {N(P['benchmark_test'])} бақылауда бағаланды. Бұл көлем KNN мен нейрондық желіні де бірдей бюджет аясында салыстыруға мүмкіндік берді. Үлкен таңдама тәжірибесінде логистикалық регрессия мен LightGBM {N(P['fit'])} бақылауда бөлек оқытылды.

Салыстырмалы кесте мен үлкен таңдама кестесінің міндеті әртүрлі. Біріншісі алгоритмдерді бірдей деректе салыстырады; екіншісі екі масштабталатын әдістің көбірек деректегі мінез-құлқын көрсетеді. Бір кестедегі көрсеткіштерді екінші кестедегі басқа көлеммен оқытылған модельге тікелей жеңіс ретінде түсіндіруге болмайды.''')
    d.h('3.2 Гиперпараметрлер және кросс-валидация',2)
    paragraphs(d,'''BRFSS салыстырмалы тәжірибесінде әр алгоритмнің бастапқы конфигурациясы үш стратификацияланған бөлікте бағаланды. Одан кейін RandomizedSearchCV арқылы үш конфигурация қаралды. Негізгі таңдау өлшемі Average Precision болды. Бұл бюджет толық оңтайландыруды білдірмейді; ол берілген компьютердегі бақыланатын және қайталанатын салыстыру болып табылады.

Барлық модельде сандық белгілерге медианалық толтыру мен масштабтау, категорияларға тұрақты белгісіз санат және one-hot кодтау қолданылды. Бұл операциялар Pipeline ішінде орналасқандықтан, сыртқы тексеру бөлігінің статистикасы оқытуға кірмейді. MLP ішкі early stopping бөлімі Pipeline түрлендіруінен кейін бөлінеді; сондықтан ол ішкі тоқтау таңдамағы бойынша толық оқшауланған рәсім емес. Бұл шектеу сыртқы тестті өңдеуге қосқанды білдірмейді. Қолданылатын санаттар ресми анықтамалықтан алынған, тесттен үйренілмеген.

UCI таңдама көлемі шағын болғандықтан, сыртқы үш бөлік екі рет қайталанды. Әр сыртқы оқыту жиынының ішінде үш бөлікті CV арқылы екі кездейсоқ конфигурация салыстырылды. Сыртқы тест бөлігі параметр таңдауына қатыспады. Нәтижелер алты сыртқы бағалаудың орташа мәні және стандартты ауытқуы түрінде ұсынылады. Соңғы қолданбалық модель барлық Cleveland дерегінде қайта оқытылды. Кейін орындалған тарихи орталықтар арасындағы аудит 4.8 бөлімде бөлек көрсетілді; ол перспективалық клиникалық тексеру емес.''')
    d.h('3.3 Калибрлеу және шек таңдау',2)
    paragraphs(d,f'''Логистикалық регрессия мен LightGBM үшін бастапқы ықтималдықтарға sigmoid калибрлеу қарастырылды. Калибратор тек арнайы бөлінген {N(P['calibration'])} бақылауда үйренді. Бастапқы және калибрленген нұсқаның Brier score мәндері валидацияда салыстырылды. Логистикалық регрессияға қосымша калибрлеу таңдалды, LightGBM үшін бастапқы ықтималдық сақталды.

Классификация шегі валидациялық F1 максимумымен анықталды. Таңдалған логистикалық модель үшін ол {B['selection']['threshold']:.6f} болды. Бұл клиникалық хаттамадан алынған қауіп шегі емес; ол зерттеудің математикалық таңдау ережесі. Оны «төмен», «орташа», «жоғары» медициналық қауіп санаттарына айналдыруға негіз жоқ.

Модельдің аты, калибрлеу шешімі және шек selection_lock.json файлында тест бағасына дейін сақталды. Тестте басқа алгоритм сәл жоғары нәтиже көрсетсе де, енгізілген модель автоматты түрде ауыстырылмайды. Осы қағида тесттің тәуелсіз бағалау рөлін сақтайды.''')
    d.h('3.4 Салмақтар және белгісіздік',2)
    paragraphs(d,'''CDC сауалнама салмақтары популяциялық дизайнмен байланысты, ал class_weight алгоритмдегі класс шығынын өзгертеді. Екеуі бір мағынаны білдірмейді. Негізгі оқыту мен таңдау респондент деңгейіндегі салмақсыз есеппен орындалды. Тестте _LLCPWT арқылы салмақталған метрикалар қосымша берілді; бөлек сезімталдық тәжірибесінде логистикалық регрессия осы салмақтармен оқытылды.

Негізгі модельдің 95% интервалдары 200 респонденттік bootstrap қайталауымен бағаланды. Модельдер арасындағы AP айырмасы бірдей қайта таңдалған жолдарда есептелді. Бұл интервалдар дайын модель шартында тест респонденттерінің өзгеруін көрсетеді. Олар модельді қайта оқыту, сауалнама стратификациясы мен кластерлік дизайнды толық қамтымайды, сондықтан популяциялық дәл интервал ретінде түсіндірілмейді.''');d.page()
    d.h('4 Нәтижелерді салыстыру және талқылау')
    d.h('4.1 Бірдей таңдамадағы алгоритмдер',2)
    d.p('1-кесте. BRFSS: 12 000 оқыту және 12 000 тест бақылауы. Барлық модель үшін шек 0,5. Көрсеткіштер салмақсыз есептелген.',style='SmallKK')
    d.table(['Модель','ROC-AUC','AP','Recall','F1','Brier'],[[r['name']]+[F(r['metrics'][k]) for k in ['roc_auc','average_precision','recall','f1','brier']] for r in B['benchmark']],[145,70,70,70,70,70])
    paragraphs(d,'''Бақылау моделі жоғары Accuracy көрсете алады, бірақ барлық объектіні теріс классқа жатқызғанда сезімталдық нөлге тең. Бұл деректерде оң класс аз болғандықтан, Accuracy жалғыз қолданылса нәтиже туралы жаңсақ әсер береді. Салыстыруда AP пен ROC-AUC, сонымен қатар таңдалған шектегі қателер бірге қаралды.

Логистикалық регрессия және сызықтық SVM шағын бірдей таңдамада жоғары нәтижелерге жетті. Ағаш пен KNN төменірек нәтиже көрсетті. MLP-тің тесттегі AP мәні CV бағасынан айтарлықтай төмен болды. Бұл нәтиже жасырылмады: берілген шағын архитектура, шектеулі баптау бюджеті және ерте тоқтау ережесі тұрақты артықшылық бермеді. Сондықтан бұл тәжірибе барлық нейрондық желілер туралы жалпы қорытынды жасауға негіз емес.''')
    d.figure('benchmark','1-сурет. Бірдей көлемдегі BRFSS тәжірибесінің Average Precision көрсеткіші.')
    d.h('4.2 Үлкен деректегі модель таңдау',2)
    d.table(['Модель','Валидация AP','Тест AP','Тест ROC-AUC','Тест Brier'],[[r['name'],F(r['validation']['average_precision']),F(r['metrics']['average_precision']),F(r['metrics']['roc_auc']),F(r['metrics']['brier'])] for r in B['full']],[150,85,85,90,85])
    paragraphs(d,f'''Валидацияда логистикалық регрессияның AP мәні {F(L['validation']['average_precision'])}, ал LightGBM мәні {F(G['validation']['average_precision'])} болды. Алдын ала бекітілген таңдау ережесі логистикалық регрессияны таңдады. Тестте LightGBM AP={F(G['metrics']['average_precision'])} нәтижесін көрсетіп, логистикалық регрессиядан AP бойынша сәл жоғары болды. Бұл факт ашық берілді, бірақ тест нәтижесіне қарап негізгі модель ауыстырылмады.

Логистикалық регрессия мен LightGBM арасындағы тест AP айырмасының жұпталған bootstrap интервалы {F(B['confidence']['paired_ap_difference'][0])} мен {F(B['confidence']['paired_ap_difference'][1])} аралығында орналасады. Ол осы бекітілген модельдер мен осы тест жиыны үшін LightGBM пайдасына шағын айырманы көрсетеді. Бұл алгоритмнің барлық жағдайдағы басымдығы немесе клиникалық тиімділігі туралы дәлел емес.

Негізгі модельдің тест ROC-AUC мәні {F(M['roc_auc'])}; 95% жуық интервалы {F(B['confidence']['roc_auc'][0])}–{F(B['confidence']['roc_auc'][1])}. AP={F(M['average_precision'])}; интервалы {F(B['confidence']['average_precision'][0])}–{F(B['confidence']['average_precision'][1])}. Шектегі сезімталдық {M['recall']:.1%}, ерекшелік {M['specificity']:.1%}, оң болжам дәлдігі {M['precision']:.1%}. Бұл көрсеткіштер модельдің қателері елеулі екенін айқын көрсетеді.''')
